'use strict';
const names={'sam-tuoi':'Sâm Nữ Hoàng tươi','sam-kho':'Sâm Nữ Hoàng khô','ruou-sam':'Ngự Vị Nữ Hoàng Tưu','cao-sam':'Cao Sâm Nữ Hoàng'};
const base=document.body.dataset.base||'./';
let saved=[],note='',storageOK=true;
try{const raw=JSON.parse(localStorage.getItem('snh-interest')||'[]');saved=Array.isArray(raw)?[...new Set(raw.filter(x=>Object.hasOwn(names,x)))]:[];note=localStorage.getItem('snh-note')||'';}catch{storageOK=false;}
function notify(text){const el=document.querySelector('.toast');el.textContent=text;el.classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.classList.remove('visible'),3300);}
function persist(){try{localStorage.setItem('snh-interest',JSON.stringify(saved));return true;}catch{storageOK=false;notify('Trình duyệt không cho phép lưu. Danh sách chỉ còn trong phiên hiện tại.');return false;}}
function render(){document.querySelectorAll('.saved-count').forEach(el=>el.textContent=saved.length);const count=document.getElementById('list-count');if(count)count.textContent=saved.length;const list=document.getElementById('inquiry-list');if(list){list.replaceChildren();if(!saved.length){const p=document.createElement('p');p.className='empty-list';p.append('Bạn chưa chọn sản phẩm. ');const a=document.createElement('a');a.href=base+'san-pham/';a.textContent='Khám phá danh mục ↗';p.append(a);list.append(p);}for(const key of saved){const row=document.createElement('div');row.className='inquiry-row';const a=document.createElement('a');a.href=base+'san-pham/'+key+'/';a.textContent=names[key];const b=document.createElement('button');b.textContent='Xóa';b.setAttribute('aria-label','Xóa '+names[key]);b.onclick=()=>{saved=saved.filter(x=>x!==key);persist();render();};row.append(a,b);list.append(row);}}document.querySelectorAll('[data-add]').forEach(b=>{const exists=saved.includes(b.dataset.add);b.textContent=exists?'Đã lưu · Xem danh sách quan tâm ↗':'Lưu vào danh sách quan tâm ＋';});}
document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.add;if(saved.includes(key)){location.href=base+'lien-he/';return;}saved.push(key);const ok=persist();render();if(ok)notify('Đã lưu sản phẩm vào danh sách quan tâm.');}));
const menu=document.querySelector('.menu-toggle'),nav=document.getElementById('main-nav');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Đóng trình đơn':'Mở trình đơn');nav.classList.toggle('open',open);});document.addEventListener('keydown',e=>{if(e.key==='Escape'){menu?.setAttribute('aria-expanded','false');nav?.classList.remove('open');}});
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});document.querySelectorAll('[data-category]').forEach(c=>c.hidden=button.dataset.filter!=='all'&&c.dataset.category!==button.dataset.filter);}));
const dialog=document.getElementById('lightbox');document.querySelectorAll('[data-image]').forEach(b=>b.addEventListener('click',()=>{dialog.querySelector('img').src=b.dataset.image;dialog.showModal();}));dialog?.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog?.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
const textarea=document.getElementById('inquiry-note');if(textarea){textarea.value=note;textarea.addEventListener('input',()=>{note=textarea.value;try{localStorage.setItem('snh-note',note);}catch{if(storageOK){storageOK=false;notify('Ghi chú chỉ được giữ trong phiên hiện tại.');}}});}
document.getElementById('download-inquiry')?.addEventListener('click',()=>{if(!saved.length&&!note.trim()){notify('Hãy chọn sản phẩm hoặc nhập nội dung bạn quan tâm.');return;}const text='SÂM NỮ HOÀNG — DANH SÁCH QUAN TÂM\n\n'+saved.map((key,i)=>(i+1)+'. '+names[key]).join('\n')+'\n\nNỘI DUNG CẦN TRAO ĐỔI\n'+note+'\n\nĐây là danh sách cá nhân, chưa phải đơn hàng và chưa được gửi tới doanh nghiệp.\n';const u=URL.createObjectURL(new Blob(['\uFEFF',text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='sam-nu-hoang-danh-sach-quan-tam.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);notify('Đã tạo tệp danh sách quan tâm.');});render();
